func validFlowGraph(g *flowGraph) bool {
	if g == nil || g.Count < 1 || g.Count > len(g.Nodes) {
		return false
	}
	for i := 0; i < g.Count; i++ {
		n := g.Nodes[i]
		if n.Count < 0 || n.Count > len(n.Children) {
			return false
		}
		for j := 0; j < n.Count; j++ {
			if n.Children[j] < 0 || n.Children[j] >= g.Count {
				return false
			}
		}
	}
	return true
}

