func walkFlowGraph(g *flowGraph, node int, marks *[4]bool, keepMarks bool) graphError {
	if marks[node] {
		return graphCycle
	}
	marks[node] = true
	for i := 0; i < g.Nodes[node].Count; i++ {
		if err := walkFlowGraph(g, g.Nodes[node].Children[i], marks, keepMarks); err != graphOK {
			return err
		}
	}
	if !keepMarks {
		marks[node] = false
	}
	return graphOK
}

