func validLifecycle(in lifecycleTrace) bool {
	if in.Count < 0 || in.Count > len(in.Events) {
		return false
	}
	begun, terminal := false, false
	for i := 0; i < in.Count; i++ {
		e := in.Events[i]
		if e < lifeBegin || e > lifeCancel {
			return false
		}
		if terminal {
			continue
		}
		if (e == lifeFinish || e == lifeFail) && !begun {
			return false
		}
		if e == lifeBegin {
			begun = true
		} else {
			terminal = true
		}
	}
	return true
}

